 import unittest
from candidate import filter_by_prefix

class TestFilterByPrefix(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_no_match(self):
        self.assertEqual(filter_by_prefix(['def', 'ghi', 'jkl'], 'a'), [])

    def test_single_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'def', 'ghi'], 'a'), ['abc'])

    def test_multiple_matches(self):
        self.assertEqual(filter_by_prefix(['abc', 'array', 'bcd', 'cde', 'def', 'ghi', 'jkl'], 'a'), ['abc', 'array'])

    def test_match_at_end(self):
        self.assertEqual(filter_by_prefix(['abc', 'array', 'bcd', 'cde', 'def', 'ghiarray', 'jkl'], 'a'), ['abc', 'array', 'ghiarray'])

    def test_match_with_prefix_in_middle(self):
        self.assertEqual(filter_by_prefix(['abcarray', 'def', 'ghi', 'jklarray'], 'a'), ['abcarray'])

    def test_match_with_empty_string(self):
        self.assertEqual(filter_by_prefix(['', 'abc', 'def', 'ghi'], 'a'), [])

    def test_match_with_none(self):
        self.assertEqual(filter_by_prefix([None, 'abc', 'def', 'ghi'], 'a'), [])

    def test_match_with_mixed_types(self):
        self.assertEqual(filter_by_prefix(['abc', 123, 'def', 'ghi'], 'a'), ['abc'])

    def test_match_with_only_numbers(self):
        self.assertEqual(filter_by_prefix([1, 2, 3, 4], 'a'), [])

if __name__ == '__main__':
    unittest.main()
